insert into public.analytics_profiles (key, position, name, owner_unit, description, spec, updated_by, updated_at) values
  ('student-count', 1, 'Student count', 'a12', 'Registrar: one row per enrolled student (SY, term, college, program, student number, load, class type, gender).', $j${"kind":"rows","headers":["STUD_NUMBER","COLLEGE","PROGRAM"],"skip":[],"measures":[{"key":"students","label":"Students","op":"distinct","column":"STUD_NUMBER"},{"key":"female","label":"Female students","op":"distinct","column":"STUD_NUMBER","where":[{"column":"GENDER","in":["F","FEMALE"]}]},{"key":"online","label":"Online students","op":"distinct","column":"STUD_NUMBER","where":[{"column":"CLASS_TYPE","match":"online"}]},{"key":"fte","label":"Full-time equivalent (21 units = 1)","op":"fte","column":"LOAD (UNITS)","full":21}],"dimensions":["COLLEGE","GENDER","CLASS_TYPE"],"minCell":5,"pairs":[]}$j$::jsonb, 'system', now()),
  ('graduate-count', 2, 'Graduate count', 'a12', 'Registrar: one row per graduate (college, degree program, student number, gender, completion date).', $j${"kind":"rows","headers":["STUD_NUMBER","DEGREE_PROGRAM","COMPLETION_DATE"],"skip":[],"measures":[{"key":"graduates","label":"Graduates","op":"distinct","column":"STUD_NUMBER"},{"key":"female","label":"Female graduates","op":"distinct","column":"STUD_NUMBER","where":[{"column":"GENDER","in":["F","FEMALE"]}]}],"dimensions":["COLLEGE","GENDER"],"minCell":5,"pairs":[]}$j$::jsonb, 'system', now()),
  ('students-starting', 3, 'Students starting a degree', 'a12', 'Registrar: first-year entrants, with any alumni parent on record (for first-generation counts).', $j${"kind":"rows","headers":["STUD_NUMBER","ENTRY_YEAR","FIRST_SY_ATTEND"],"skip":[],"measures":[{"key":"starting","label":"Students starting a degree","op":"distinct","column":"STUD_NUMBER"},{"key":"women","label":"Women starting a degree","op":"distinct","column":"STUD_NUMBER","where":[{"column":"GENDER","in":["F","FEMALE"]}]},{"key":"alumni-parent","label":"With a parent who is a UST alumnus","op":"distinct","column":"STUD_NUMBER","where":[{"column":"ALUMNI_TYPE","empty":false}]}],"dimensions":["COLLEGE","GENDER"],"minCell":5,"pairs":[]}$j$::jsonb, 'system', now()),
  ('academic-staff', 4, 'Academic staff', 'hrd', 'HR: one row per faculty member (college, program, tenure, rank, hire dates, gender).', $j${"kind":"rows","headers":["EMP_NUMBER","COLLEGE_AFFILIATION","RANK"],"skip":[],"measures":[{"key":"staff","label":"Academic staff","op":"distinct","column":"EMP_NUMBER"},{"key":"female","label":"Female academic staff","op":"distinct","column":"EMP_NUMBER","where":[{"column":"GENDER","in":["F","FEMALE"]}]},{"key":"senior","label":"Senior academic staff (professors and associate professors)","op":"distinct","column":"EMP_NUMBER","where":[{"column":"RANK","match":"^(PROF|ASSOC)"}]},{"key":"female-senior","label":"Female senior academic staff","op":"distinct","column":"EMP_NUMBER","where":[{"column":"GENDER","in":["F","FEMALE"]},{"column":"RANK","match":"^(PROF|ASSOC)"}]},{"key":"tenured","label":"Tenured","op":"distinct","column":"EMP_NUMBER","where":[{"column":"TENURESHIP","in":["T","TENURED"]}]}],"dimensions":["COLLEGE_AFFILIATION","GENDER","TENURESHIP"],"minCell":5,"pairs":[]}$j$::jsonb, 'system', now()),
  ('support-staff', 5, 'Support staff', 'hrd', 'HR: one row per non-teaching employee (office, employment date, status, gender).', $j${"kind":"rows","headers":["Employee_Number","Office/Department","Status"],"skip":[],"measures":[{"key":"staff","label":"Support staff","op":"distinct","column":"Employee_Number"},{"key":"female","label":"Female support staff","op":"distinct","column":"Employee_Number","where":[{"column":"Gender","in":["F","FEMALE"]}]},{"key":"regular","label":"Regular (secure contracts)","op":"distinct","column":"Employee_Number","where":[{"column":"Status","in":["REGULAR","PERMANENT"]}]}],"dimensions":["Status","Gender"],"minCell":5,"pairs":[]}$j$::jsonb, 'system', now()),
  ('disability', 6, 'Persons with disability', 'a30', 'Health Service: students and employees with a disability on record. Only the ID (to count once) and the student or employee tag are read; assessments never are.', $j${"kind":"rows","headers":["ID_NO","Tagging"],"skip":[],"measures":[{"key":"students","label":"Students with disability","op":"distinct","column":"ID_NO","where":[{"column":"Tagging","match":"student"}]},{"key":"employees","label":"Employees with disability","op":"distinct","column":"ID_NO","where":[{"column":"Tagging","match":"employee|staff|faculty"}]}],"dimensions":["Tagging"],"minCell":5,"pairs":[]}$j$::jsonb, 'system', now()),
  ('course-offering', 7, 'Course offering schedule', 'a12', 'Registrar: class schedules (course code and description per enrolled student). Courses are counted once; sustainability courses by keywords in the description.', $j${"kind":"rows","headers":["COURSE_NAME","DESCRIPTION","STUD_NUMBER"],"skip":[],"measures":[{"key":"courses","label":"Courses offered","op":"distinct","column":"COURSE_NAME"},{"key":"sustainability","label":"Sustainability-related courses (by keyword)","op":"distinct","column":"COURSE_NAME","where":[{"column":"DESCRIPTION","match":"sustainab|environment|ecolog|climate|green|renewable|conservation|biodivers|\\bSDG|energy|water resource|waste|disaster|resilien"}]},{"key":"students","label":"Students enrolled","op":"distinct","column":"STUD_NUMBER"}],"dimensions":["SEC_COLLEGE"],"minCell":5,"pairs":[]}$j$::jsonb, 'system', now()),
  ('research-funds', 8, 'Research funds', 'vrri', 'Research office: funded projects with their expenditure in pesos and source of funds.', $j${"kind":"rows","headers":["Project name","Total expenditure amount","Source of funds"],"skip":[{"column":"Project name","empty":true}],"measures":[{"key":"projects","label":"Funded projects","op":"count"},{"key":"total","label":"Total expenditure (PHP)","op":"sum","column":"Total expenditure amount"},{"key":"sustainability","label":"Sustainability research (PHP, by keyword)","op":"sum","column":"Total expenditure amount","where":[{"column":"Project name","match":"sustainab|environment|ecolog|climate|green|renewable|conservation|biodivers|\\bSDG|energy|water resource|waste|disaster|resilien"}]}],"dimensions":[],"minCell":1,"pairs":[]}$j$::jsonb, 'system', now()),
  ('fmo-figures', 9, 'FMO figures', 'fmo', 'Facilities Management: water, population, energy, floor space and food waste figures, one per row.', $j${"kind":"pairs","headers":[],"skip":[],"measures":[],"dimensions":[],"minCell":1,"pairs":[{"label":"Volume of water used in the university: Inbound (treated/ extracted water)","key":"water"},{"label":"Campus population","key":"population"},{"label":"Total energy used","key":"energy"},{"label":"University floor space","key":"floor"},{"label":"Total food waste","key":"food-waste"}]}$j$::jsonb, 'system', now())
