-- The analytics engine (src/lib/analytics, docs/analytics-engine.md).
--
-- Methodology as data: an edition of a ranking (UI GreenMetric 2026, THE Impact 2027…) holds groups and indicators,
-- each with how it is entered and how it scores. Facts sit beside the catalog, outside the governance store, so a busy
-- collection season never rewrites it: values (the University's and each unit's), evidence links, the activity
-- register, peer benchmarks, WURI cases and their reviews, template uploads (counts only), request campaigns, action
-- items and snapshots. Reports are computed from these, never stored except as snapshots. Every change is audited
-- through the store's audit trail by the server actions in src/app/actions/analytics.ts. Only the service role reads
-- or writes these tables.

-- ---------- Catalog ----------

create table public.analytics_editions (
  id text primary key check (id ~ '^[a-z0-9][a-z0-9-]{2,63}$'),
  ranking_slug text not null references public.ranking_frameworks (slug) on delete cascade,
  year integer not null check (year between 2000 and 2100),
  label text not null check (char_length(label) between 1 and 160),
  methodology text not null default '' check (char_length(methodology) <= 200),
  period text not null default '' check (char_length(period) <= 200),
  status text not null default 'Draft' check (status in ('Draft', 'Active', 'Closed', 'Archived')),
  scale numeric not null default 100 check (scale > 0),
  aggregate text not null default 'sum' check (aggregate in ('sum', 'the-impact', 'best-per-group', 'readiness', 'results')),
  options jsonb not null default '{}'::jsonb check (jsonb_typeof(options) = 'object'),
  sources text[] not null default '{}',
  notes text not null default '' check (char_length(notes) <= 4000),
  opens_on date,
  closes_on date,
  -- Calendar years evidence may come from.
  years integer[] not null default '{}',
  updated_by text not null default 'system',
  updated_at timestamptz not null default now(),
  unique (ranking_slug, year)
);

create table public.analytics_groups (
  edition_id text not null references public.analytics_editions (id) on delete cascade,
  code text not null check (code ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$'),
  position integer not null,
  name text not null check (char_length(name) between 1 and 400),
  points numeric check (points >= 0),
  weight numeric check (weight between 0 and 1),
  mandatory boolean not null default false,
  primary key (edition_id, code)
);

create table public.analytics_indicators (
  edition_id text not null,
  code text not null check (code ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$'),
  position integer not null,
  group_code text not null,
  parent_code text,
  ref text check (char_length(ref) <= 32),
  name text not null check (char_length(name) between 1 and 400),
  guidance text not null default '' check (char_length(guidance) <= 4000),
  unit text check (char_length(unit) <= 40),
  -- What is entered (lib/analytics/types.ts InputSpec) and how it scores (ScoreRule); checked by lib/analytics/pack.ts.
  input jsonb not null default '{"type": "none"}'::jsonb check (jsonb_typeof(input) = 'object' and input ? 'type'),
  score jsonb check (score is null or (jsonb_typeof(score) = 'object' and score ? 'kind')),
  evidence jsonb not null default '{}'::jsonb check (jsonb_typeof(evidence) = 'object'),
  owners text[] not null default '{}',
  owner_labels text[] not null default '{}',
  rollup text not null default 'office' check (rollup in ('office', 'sum', 'max', 'latest')),
  feeds jsonb check (feeds is null or jsonb_typeof(feeds) = 'array'),
  tags text[] not null default '{}',
  primary key (edition_id, code),
  foreign key (edition_id, group_code) references public.analytics_groups (edition_id, code) on delete cascade
);

-- ---------- Facts ----------

create table public.analytics_values (
  id uuid primary key default gen_random_uuid(),
  edition_id text not null,
  indicator_code text not null,
  -- '' is the University's own figure, compiled by the Office; otherwise the unit that supplied it.
  unit_id text not null default '',
  value jsonb not null check (jsonb_typeof(value) = 'object'),
  note text not null default '' check (char_length(note) <= 2000),
  source text not null default 'manual' check (source in ('manual', 'import', 'template', 'register', 'portal')),
  source_ref text check (char_length(source_ref) <= 120),
  status text not null default 'For review' check (status in ('Draft', 'For review', 'Validated', 'Needs revision', 'Not applicable')),
  entered_by text not null,
  entered_at timestamptz not null default now(),
  reviewed_by text,
  reviewed_at timestamptz,
  review_note text check (char_length(review_note) <= 2000),
  unique (edition_id, indicator_code, unit_id),
  foreign key (edition_id, indicator_code) references public.analytics_indicators (edition_id, code) on delete cascade
);
create index analytics_values_unit_idx on public.analytics_values (unit_id, edition_id);

-- Every change to a value, newest last: who entered, changed, validated or returned it, and what it said then.
create table public.analytics_value_history (
  id bigint generated always as identity primary key,
  value_id uuid not null references public.analytics_values (id) on delete cascade,
  at timestamptz not null default now(),
  by text not null,
  action text not null check (action in ('entered', 'changed', 'validated', 'returned', 'not-applicable', 'reopened', 'imported')),
  value jsonb not null,
  status text not null,
  note text not null default '' check (char_length(note) <= 2000)
);
create index analytics_value_history_idx on public.analytics_value_history (value_id, at);

create table public.analytics_links (
  id uuid primary key default gen_random_uuid(),
  edition_id text not null,
  indicator_code text not null,
  unit_id text not null default '',
  -- An evidence record in the governance store, or a web address.
  evidence_id text check (char_length(evidence_id) <= 40),
  url text check (url is null or (char_length(url) <= 2000 and url ~ '^https://')),
  label text not null default '' check (char_length(label) <= 300),
  year integer check (year between 1900 and 2100),
  relevance text check (relevance in ('specific', 'general', 'not relevant')),
  public boolean,
  self_contained boolean,
  assessed_by text,
  assessed_at timestamptz,
  added_by text not null,
  added_at timestamptz not null default now(),
  check (evidence_id is not null or url is not null),
  foreign key (edition_id, indicator_code) references public.analytics_indicators (edition_id, code) on delete cascade
);
create index analytics_links_indicator_idx on public.analytics_links (edition_id, indicator_code);
create unique index analytics_links_once_idx on public.analytics_links (edition_id, indicator_code, unit_id, coalesce(evidence_id, ''), coalesce(url, ''));

-- The activity register: service learning, community development, advocacy… by unit and academic year.
create table public.analytics_activities (
  id uuid primary key default gen_random_uuid(),
  unit_id text,
  unit_label text not null default '' check (char_length(unit_label) <= 120),
  kind text not null check (kind in ('Service learning', 'Community development', 'Advocacy', 'Outreach', 'Event', 'Research', 'Other')),
  academic_year text not null check (academic_year ~ '^\d{4}-\d{4}$'),
  title text not null check (char_length(title) between 1 and 300),
  proponent text not null default '' check (char_length(proponent) <= 200),
  community text not null default '' check (char_length(community) <= 400),
  proposal_ref text check (char_length(proposal_ref) <= 300),
  report_ref text check (char_length(report_ref) <= 300),
  reported boolean not null default false,
  sdgs integer[] not null default '{}',
  beneficiaries integer check (beneficiaries >= 0),
  partner text not null default '' check (char_length(partner) <= 300),
  mou text check (char_length(mou) <= 2000),
  starts_on date,
  ends_on date,
  tags text[] not null default '{}',
  source text not null default 'manual' check (source in ('manual', 'import', 'portal')),
  source_ref text check (char_length(source_ref) <= 120),
  added_by text not null,
  added_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index analytics_activities_once_idx on public.analytics_activities (academic_year, kind, lower(title), coalesce(unit_id, lower(unit_label)));
create index analytics_activities_year_idx on public.analytics_activities (academic_year);

-- ---------- Benchmarks ----------

create table public.analytics_peers (
  id text primary key default gen_random_uuid()::text,
  name text not null unique check (char_length(name) between 1 and 200),
  country text not null default '' check (char_length(country) <= 80),
  band text not null default 'Other' check (band in ('Philippines', 'ASEAN', 'Aspirational', 'Other')),
  added_by text not null,
  added_at timestamptz not null default now()
);

-- Published results: the University's own (peer_id '') and its peers'. metric is an indicator or group code,
-- "overall", or "<subject>:<indicator>" ("medicine:rank").
create table public.analytics_benchmarks (
  id uuid primary key default gen_random_uuid(),
  ranking_slug text not null references public.ranking_frameworks (slug) on delete cascade,
  year integer not null check (year between 2000 and 2100),
  peer_id text not null default '',
  metric text not null check (char_length(metric) between 1 and 120),
  value numeric,
  label text check (char_length(label) <= 40),
  source text not null default 'manual' check (source in ('manual', 'import')),
  note text check (char_length(note) <= 300),
  entered_by text not null,
  entered_at timestamptz not null default now(),
  check (value is not null or label is not null),
  unique (ranking_slug, year, peer_id, metric)
);
create index analytics_benchmarks_metric_idx on public.analytics_benchmarks (ranking_slug, metric, year);

-- ---------- WURI cases ----------

create table public.analytics_cases (
  id uuid primary key default gen_random_uuid(),
  edition_id text not null,
  category text not null,
  title text not null check (char_length(title) between 1 and 300),
  unit_id text,
  abstract text not null default '' check (char_length(abstract) <= 4000),
  source text not null default 'manual' check (source in ('manual', 'import')),
  source_ref text check (char_length(source_ref) <= 260),
  checks jsonb not null default '[]'::jsonb check (jsonb_typeof(checks) = 'array'),
  added_by text not null,
  added_at timestamptz not null default now(),
  foreign key (edition_id, category) references public.analytics_indicators (edition_id, code) on delete cascade
);
create index analytics_cases_edition_idx on public.analytics_cases (edition_id, category);

create table public.analytics_reviews (
  id uuid primary key default gen_random_uuid(),
  case_id uuid not null references public.analytics_cases (id) on delete cascade,
  reviewer_id text not null,
  scores jsonb not null check (jsonb_typeof(scores) = 'object'),
  total numeric not null check (total >= 0),
  note text not null default '' check (char_length(note) <= 2000),
  at timestamptz not null default now(),
  unique (case_id, reviewer_id)
);

-- ---------- Imports ----------

-- Template profiles (lib/analytics/templates.ts Profile): which headers identify a template and what to count.
create table public.analytics_profiles (
  key text primary key check (key ~ '^[a-z0-9][a-z0-9-]{1,47}$'),
  position integer not null default 0,
  name text not null check (char_length(name) between 1 and 120),
  owner_unit text,
  description text not null default '' check (char_length(description) <= 600),
  spec jsonb not null check (jsonb_typeof(spec) = 'object'),
  updated_by text not null,
  updated_at timestamptz not null default now()
);

-- Every file read: its fingerprint and what came of it. A template upload keeps only counts (totals, and breakdowns
-- without cells under the profile's minimum); the rows themselves are never stored anywhere.
create table public.analytics_imports (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('template', 'workbook', 'register', 'benchmarks', 'pack', 'evidence-docs', 'cases')),
  profile text,
  file_name text not null check (char_length(file_name) <= 260),
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  bytes integer not null check (bytes >= 0),
  rows integer not null default 0,
  edition_id text,
  unit_id text,
  academic_year text check (academic_year ~ '^\d{4}-\d{4}$'),
  summary jsonb not null default '{}'::jsonb check (jsonb_typeof(summary) = 'object'),
  totals jsonb check (totals is null or jsonb_typeof(totals) = 'object'),
  breakdowns jsonb check (breakdowns is null or jsonb_typeof(breakdowns) = 'array'),
  by text not null,
  at timestamptz not null default now()
);
create index analytics_imports_profile_idx on public.analytics_imports (profile, at desc);

-- How activity registers name units (AB, AMV-COA) → org_units ids.
create table public.analytics_aliases (
  alias text primary key check (char_length(alias) between 1 and 60),
  unit_id text not null
);

-- ---------- Requests ----------

create table public.analytics_campaigns (
  id uuid primary key default gen_random_uuid(),
  code text not null unique check (code ~ '^REQ-\d{3,6}$'),
  edition_id text not null references public.analytics_editions (id) on delete cascade,
  title text not null check (char_length(title) between 1 and 160),
  memo text not null default '' check (char_length(memo) <= 120),
  message text not null default '' check (char_length(message) <= 4000),
  due date not null,
  status text not null default 'Open' check (status in ('Open', 'Closed')),
  remind_days integer not null default 7 check (remind_days between 1 and 60),
  escalate_days integer not null default 3 check (escalate_days between 0 and 60),
  opened_by text not null,
  opened_at timestamptz not null default now(),
  closed_at timestamptz
);

create table public.analytics_campaign_units (
  campaign_id uuid not null references public.analytics_campaigns (id) on delete cascade,
  unit_id text not null,
  codes text[] not null default '{}',
  reminded_at timestamptz,
  reminders integer not null default 0 check (reminders >= 0),
  escalated_at timestamptz,
  thanked_at timestamptz,
  primary key (campaign_id, unit_id)
);

-- ---------- Outputs ----------

create table public.analytics_actions (
  id uuid primary key default gen_random_uuid(),
  edition_id text not null references public.analytics_editions (id) on delete cascade,
  indicator_code text,
  action text not null check (char_length(action) between 1 and 300),
  owner_unit text,
  due date,
  status text not null default 'Not started' check (status in ('Not started', 'On track', 'At risk', 'Complete')),
  progress integer not null default 0 check (progress between 0 and 100),
  note text not null default '' check (char_length(note) <= 2000),
  updated_by text not null,
  updated_at timestamptz not null default now()
);

create table public.analytics_snapshots (
  id uuid primary key default gen_random_uuid(),
  edition_id text not null references public.analytics_editions (id) on delete cascade,
  at timestamptz not null default now(),
  by text not null,
  kind text not null check (kind in ('auto', 'manual')),
  summary jsonb not null check (jsonb_typeof(summary) = 'object')
);
create index analytics_snapshots_edition_idx on public.analytics_snapshots (edition_id, at desc);

-- ---------- Access: the service role only ----------

do $$
declare
  t text;
begin
  foreach t in array array[
    'analytics_editions', 'analytics_groups', 'analytics_indicators', 'analytics_values', 'analytics_value_history',
    'analytics_links', 'analytics_activities', 'analytics_peers', 'analytics_benchmarks', 'analytics_cases',
    'analytics_reviews', 'analytics_profiles', 'analytics_imports', 'analytics_aliases', 'analytics_campaigns',
    'analytics_campaign_units', 'analytics_actions', 'analytics_snapshots'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
  end loop;
end;
$$;

